def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    if n < 10:
        if opp[-1] == 'D':
            return 'D'
        return 'C'
    opp_def_recent = sum(1 for a in opp[-10:] if a == 'D')
    me_def_recent = sum(1 for a in me[-10:] if a == 'D')
    opp_def_total = sum(1 for a in opp if a == 'D')
    # Hard punishment of sustained defectors
    if opp_def_recent >= 8:
        return 'D'
    if n >= 20:
        recent_opp_def = sum(1 for a in opp[-5:] if a == 'D')
        earlier_opp_def = sum(1 for a in opp[-20:-5] if a == 'D')
        if recent_opp_def >= 3 and earlier_opp_def <= 2:
            return 'D'
    # Late-game exploitation: if opponent has been cooperative, grab DC
    if n >= 90:
        if opp_def_total <= n // 5:
            return 'D'
        if opp_def_recent >= 6:
            return 'D'
    # Retaliation
    if last_opp == 'D' and last_me == 'C':
        if n >= 3 and opp[-2] == 'C' and opp[-3] == 'C':
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'
    if last_opp == 'D' and last_me == 'D':
        if n >= 4 and opp[-3:-1] == ['C', 'C']:
            return 'C'
        # Break DD cycle occasionally to recover cooperation
        if rng.random() < 0.12:
            return 'C'
        return 'D'
    # Opponent cooperated
    if last_opp == 'C':
        # Punish our own over-defection
        if me_def_recent >= 6:
            if rng.random() < 0.35:
                return 'D'
        if opp_def_recent >= 5:
            if rng.random() < 0.3:
                return 'D'
        # Occasional probe of cooperative opponents
        if opp_def_total == 0 and n >= 15 and n < 90:
            if rng.random() < 0.06:
                return 'D'
        return 'C'
    return 'C'
